for(const d of f.doors){const g=doorGeometry(d);if(!g)continue;const [x1,y1,x2,y2]=g.axis==='h'?[g.start,g.fixed,g.end,g.fixed]:[g.fixed,g.start,g.fixed,g.end];s+=`<g class="door" data-door="${esc(d.id)}"><path d="M${x1} ${y1}L${x2} ${y2}" stroke="#f7f7f2" stroke-width=".34"/><path d="M${x1} ${y1}L${g.axis==='h'?x1:x1+d.width} ${g.axis==='h'?y1-d.width:y1}" fill="none" stroke="${d.sealed?'#a25932':'#62787d'}" stroke-width=".07"/><path d="M${x2} ${y2}A${d.width} ${d.width} 0 0 0 ${g.axis==='h'?x1:x1+d.width} ${g.axis==='h'?y1-d.width:y1}" fill="none" stroke="#819296" stroke-width=".055" stroke-dasharray=".12 .09"/>${d.sealed?`<path d="M${x1} ${y1}L${x2} ${y2}" stroke="#a25932" stroke-width=".2" stroke-dasharray=".2 .15"/>`:''}<path d="M${x1} ${y1}L${x2} ${y2}" stroke="transparent" stroke-width=".8"/></g>`}
